def skill():
    tbl = {1.0: Rational('0.341'), 1.5: Rational('0.433'), 2.0: Rational('0.477'), 2.5: Rational('0.494')}
    p = Rational(1, 3)*Rational(1, 4) + Rational(2, 3)*Rational(1, 8)
    n = 720
    sd = sqrt(n*p*(1 - p))
    mean = n*p
    z1, z2 = (100 - mean)/sd, (145 - mean)/sd
    return 1000*(tbl[abs(float(z1))] + tbl[abs(float(z2))])

def standard():
    tbl = {1.0: Rational('0.341'), 1.5: Rational('0.433'), 2.0: Rational('0.477'), 2.5: Rational('0.494')}
    from itertools import product
    # 전수: 눈 6가지 × 동전 결과 (2번 또는 3번)
    zero = Fraction(0)
    for eye in range(1, 7):
        nc = 2 if eye <= 2 else 3
        zero += Fraction(1, 6) * Fraction(1, 2**nc)   # 앞면 0번 = 모두 뒷면
    n = 720
    mean = n*Rational(zero.numerator, zero.denominator)
    var = mean*(1 - Rational(zero.numerator, zero.denominator))
    sd = sqrt(var)
    a, b = (100 - mean)/sd, (145 - mean)/sd
    return 1000*(tbl[abs(float(a))] + tbl[abs(float(b))])

def unique():
    return [standard()]
